INSERT INTO t_permission(name,code,type,parent_id,path,method,status,sort,create_time,update_time,del_flag) SELECT '分页查询画像用户','ai:memory:user-list:api','api',p.id,'/v1/agent-console/memory/users','GET','active',0,NOW(),NOW(),0 FROM t_permission p WHERE p.code='ai:memory' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_permission WHERE code='ai:memory:user-list:api' AND del_flag=0);
INSERT INTO t_permission(name,code,type,parent_id,path,method,status,sort,create_time,update_time,del_flag) SELECT '查看指定用户通用画像','ai:memory:user-read:api','api',p.id,'/v1/agent-console/memory/users/{userId}/profile','GET','active',0,NOW(),NOW(),0 FROM t_permission p WHERE p.code='ai:memory' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_permission WHERE code='ai:memory:user-read:api' AND del_flag=0);
INSERT INTO t_permission(name,code,type,parent_id,path,method,status,sort,create_time,update_time,del_flag) SELECT '修改指定用户通用画像','ai:memory:user-edit:api','api',p.id,'/v1/agent-console/memory/users/{userId}/fields/{field}','PUT','active',0,NOW(),NOW(),0 FROM t_permission p WHERE p.code='ai:memory' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_permission WHERE code='ai:memory:user-edit:api' AND del_flag=0);
INSERT INTO t_permission(name,code,type,parent_id,path,method,status,sort,create_time,update_time,del_flag) SELECT '忘记指定用户通用画像字段','ai:memory:user-forget:api','api',p.id,'/v1/agent-console/memory/users/{userId}/fields/{field}','DELETE','active',0,NOW(),NOW(),0 FROM t_permission p WHERE p.code='ai:memory' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_permission WHERE code='ai:memory:user-forget:api' AND del_flag=0);
INSERT INTO t_permission(name,code,type,parent_id,path,method,status,sort,create_time,update_time,del_flag) SELECT '查看指定用户画像候选','ai:memory:user-review-read:api','api',p.id,'/v1/agent-console/memory/users/{userId}/reviews','GET','active',0,NOW(),NOW(),0 FROM t_permission p WHERE p.code='ai:memory' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_permission WHERE code='ai:memory:user-review-read:api' AND del_flag=0);
INSERT INTO t_permission(name,code,type,parent_id,path,method,status,sort,create_time,update_time,del_flag) SELECT '审核指定用户画像候选','ai:memory:user-review:api','api',p.id,'/v1/agent-console/memory/users/{userId}/reviews/{id}','PUT','active',0,NOW(),NOW(),0 FROM t_permission p WHERE p.code='ai:memory' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_permission WHERE code='ai:memory:user-review:api' AND del_flag=0);
INSERT INTO t_role_permission(role_id,permission_id,create_time,update_time,del_flag) SELECT r.id,p.id,NOW(),NOW(),0 FROM t_role r CROSS JOIN t_permission p WHERE r.code='superAdmin' AND r.status='active' AND r.del_flag=0 AND p.code LIKE 'ai:memory:user-%:api' AND p.status='active' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_role_permission rp WHERE rp.role_id=r.id AND rp.permission_id=p.id AND rp.del_flag=0);
